-- Municípios brasileiros: coordenada, população (IBGE 2021) e nome de exibição.
-- Gerado de `backend/app/data/municipios.json`; não editar à mão.
--   npx wrangler d1 execute zleilao --file schema/003_municipios.sql
--
-- `apelido = 1` é a grafia sem apóstrofo ("santa barbara doeste"), que existe
-- para casar o que as fontes escrevem e fica fora do autocomplete. No backend
-- em Python essa linha é criada em memória; aqui precisa estar na tabela.

CREATE TABLE IF NOT EXISTS municipios (
  nome_norm TEXT    NOT NULL,
  uf        TEXT    NOT NULL,
  nome      TEXT    NOT NULL,
  lat       REAL    NOT NULL,
  lng       REAL    NOT NULL,
  populacao INTEGER NOT NULL DEFAULT 0,
  apelido   INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (uf, nome_norm)
);
CREATE INDEX IF NOT EXISTS ix_municipios_busca ON municipios(nome_norm, populacao DESC);

DELETE FROM municipios;
